func TestRustSpecGenerated(t *testing.T) {
	m, err := load(writeRegistry(t, map[string]string{"a.yaml": tsFixture}))
	if err != nil {
		t.Fatal(err)
	}
	src, err := genRustSpec(m)
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"// Code generated by specgen from spec/registry (spec 1.0.0). DO NOT EDIT.\n",
		`pub const SCHEMA_URL: &str = "https://schemas.o11y.ing/libo11y/1.0.0";`,
		`pub const SPEC_VERSION: &str = "1.0.0";`,
		`pub const SEMCONV_VERSION: &str = "1.41.0";`,
		`pub const EVENT_NAME_KEY: &str = "event.name";`,
		"pub enum Outcome {\n    /// The value `success`.\n    Success,\n    /// The value `needs-review`.\n    NeedsReview,\n}\n",
		`    pub const KEY: &'static str = "o11y.outcome";`,
		"    pub const ALL: &'static [Self] = &[Self::Success, Self::NeedsReview];",
		`            Self::NeedsReview => "needs-review",`,
		`            "needs-review" => Ok(Self::NeedsReview),`,
		"impl core::str::FromStr for Outcome {",
		"impl core::fmt::Display for Outcome {",
		`    pub const OUTCOME: &str = "o11y.outcome";`,
		`    pub const TENANT_ID: &str = "o11y.tenant.id";`,
		`    pub const THING_HAPPENED: &str = "o11y.thing.happened";`,
		`    pub const THINGS: &str = "o11y.things";`,
		"pub mod attr {",
		"pub mod event {",
		"pub mod metric {",
		"    fn outcome_round_trips() {",
	} {
		if !strings.Contains(src, want) {
			t.Errorf("genRustSpec missing %s\n%s", want, src)
		}
	}
}

