// TestRustTablesCarryTheAppRegistryRules pins that the Rust validator gets
// every reserved namespace from the Go source of truth, in the sorted
// order the Rust side binary searches.
func TestRustTablesCarryTheAppRegistryRules(t *testing.T) {
	m, err := load(writeRegistry(t, map[string]string{"a.yaml": tsFixture}))
	if err != nil {
		t.Fatal(err)
	}
	src, err := genRustTables(m)
	if err != nil {
		t.Fatal(err)
	}
	const decl = "pub static APP_RESERVED_NAMESPACES: &[&str] = &["
	start := strings.Index(src, decl)
	if start < 0 {
		t.Fatalf("no %q slice in:\n%s", decl, src)
	}
	body, _, _ := strings.Cut(src[start+len(decl):], "];")
	var got []string
	for field := range strings.SplitSeq(body, ",") {
		if field = strings.TrimSpace(field); field != "" {
			got = append(got, strings.Trim(field, `"`))
		}
	}
	if want := appregistry.ReservedNamespaces(); !slices.Equal(got, want) {
		t.Errorf("APP_RESERVED_NAMESPACES = %v, want %v", got, want)
	}
}

func TestRustNames(t *testing.T) {
	for in, want := range map[string]string{
		"o11y.outcome":             "Outcome",
		"o11y.rum.platform":        "RumPlatform",
		"o11y.data.classification": "DataClassification",
		"react_native":             "ReactNative",
		"type_2g":                  "Type2g",
		"slow-2g":                  "Slow2g",
		"ios":                      "Ios",
	} {
		if got := rustTypeName(in); got != want {
			t.Errorf("rustTypeName(%q) = %q, want %q", in, got, want)
		}
	}
	for in, want := range map[string]string{
		"o11y.outcome":                  "OUTCOME",
		"o11y.rum.connection.effective": "RUM_CONNECTION_EFFECTIVE",
		"k8s.pod.uid":                   "K8S_POD_UID",
		"cloud.availability_zone":       "CLOUD_AVAILABILITY_ZONE",
		"a-b.c":                         "A_B_C",
	} {
		if got := rustConstName(in); got != want {
			t.Errorf("rustConstName(%q) = %q, want %q", in, got, want)
		}
	}
}

func TestRustQuote(t *testing.T) {
	for in, want := range map[string]string{
		`plain`:      `"plain"`,
		`a "quote"`:  `"a \"quote\""`,
		"line\nfeed": `"line\nfeed"`,
		"tab\there":  `"tab\there"`,
		`back\slash`: `"back\\slash"`,
		"bell\a":     `"bell\u{7}"`,
		"nel\u0085":  `"nel\u{85}"`,
		"café":       "\"café\"",
		"nul\x00":    `"nul\0"`,
	} {
		if got := rustQuote(in); got != want {
			t.Errorf("rustQuote(%q) = %s, want %s", in, got, want)
		}
	}
}

// TestRustRejectsNameCollisions pins that the generator refuses a registry
// whose names would collide in the Rust crate, rather than emit code that
// fails to compile or, through the crate root's glob re-exports, silently
// shadows a hand-written type.
func TestRustRejectsNameCollisions(t *testing.T) {
	cases := []struct {
		name string
		doc  string
		want string
	}{
		{"enum shadows a crate type", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.sensitivity
        type:
          members:
            - {id: a, value: "a"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
`, "Sensitivity"},
		{"attribute constants collide", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.tenant.id
        type: string
        annotations: {o11y.sensitivity: internal, o11y.cardinality: bounded}
      - id: o11y.tenant_id
        type: string
        annotations: {o11y.sensitivity: internal, o11y.cardinality: bounded}
`, "TENANT_ID"},
		{"variant is not an identifier", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.speed
        type:
          members:
            - {id: 2g, value: "2g"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
`, "2g"},
		{"enum shadows a prelude type", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.result
        type:
          members:
            - {id: a, value: "a"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
`, "Result"},
		{"minted enum takes the Environment name", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.environment
        type:
          members:
            - {id: a, value: "a"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
`, "Environment"},
		{"two enums become one type", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.data.kind
        type:
          members:
            - {id: a, value: "a"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
      - id: o11y.data_kind
        type:
          members:
            - {id: a, value: "a"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
`, "DataKind"},
		{"two members become one variant", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.speed
        type:
          members:
            - {id: slow_2g, value: "slow-2g"}
            - {id: slow.2g, value: "slow.2g"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
`, "Slow2g"},
		{"variant collides with an associated const", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.speed
        type:
          members:
            - {id: ALL, value: "all"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
`, "ALL"},
		{"value holds a backtick", "\ngroups:\n  - id: registry.o11y\n    type: attribute_group\n    attributes:\n      - id: o11y.speed\n        type:\n          members:\n            - {id: a, value: \"a`b\"}\n        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}\n", "backtick"},
		{"value holds a newline", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.speed
        type:
          members:
            - {id: a, value: "a\nb"}
        annotations: {o11y.sensitivity: public, o11y.cardinality: enum}
`, "unprintable"},
		{"minted key collides with a copied key", `
groups:
  - id: registry.o11y
    type: attribute_group
    attributes:
      - id: o11y.k8s.pod.uid
        type: string
        annotations: {o11y.sensitivity: internal, o11y.cardinality: bounded}
  - id: libo11y.resource.tier1
    type: attribute_group
    attributes:
      - ref: k8s.pod.uid
        annotations: {o11y.gen: copy}
`, "K8S_POD_UID"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			m, err := load(writeRegistry(t, map[string]string{"a.yaml": tc.doc}))
			if err != nil {
				t.Fatal(err)
			}
			_, err = genRustSpec(m)
			if !errors.Is(err, errRustName) || !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("genRustSpec error = %v, want one naming %q", err, tc.want)
			}
		})
	}
}

func TestRustGoPrintGenerated(t *testing.T) {
	src := genRustGoPrint()
	header := "// Code generated by specgen from Go's unicode.IsPrint (Unicode " + unicode.Version + "). DO NOT EDIT.\n"
	if !strings.HasPrefix(src, header) {
		t.Fatalf("header: got %q", src[:min(len(src), len(header))])
	}
	if !strings.Contains(src, "pub static GO_PRINT_RANGES: &[u32] = &[\n") {
		t.Fatalf("no GO_PRINT_RANGES slice in:\n%s", src)
	}
	// The TypeScript array and the Rust slice hold the same bounds.
	numbers := func(s, open, close string) string {
		start := strings.Index(s, open)
		end := strings.LastIndex(s, close)
		return strings.Join(strings.FieldsFunc(s[start+len(open):end], func(r rune) bool { return r == ',' || unicode.IsSpace(r) }), ",")
	}
	if strings.ReplaceAll(numbers(src, "&[u32] = &[", "];"), "_", "") != numbers(genTSGoPrint(), "readonly number[] = [", "];") {
		t.Fatal("the Rust slice and the TypeScript array hold different bounds")
	}
}

func TestRenderWritesRust(t *testing.T) {
	m, err := load(writeRegistry(t, map[string]string{"a.yaml": tsFixture}))
	if err != nil {
		t.Fatal(err)
	}
	outputs, err := render(m)
	if err != nil {
		t.Fatal(err)
	}
	for _, rel := range []string{rustSpecPath, rustTablesPath, rustGoPrintPath} {
		if outputs[rel] == "" {
			t.Errorf("render does not write %s", rel)
		}
	}
}

